    public static int plOwed(emon.Planctx.Plan p) {
        // How many requests of the round have no answer yet.
        int n = emon.Port.cellsLen(p.reqs);
        int at = 0;
        int k = 0;
        while (at < n) {
            if (Plan.recFind(p.got, emon.Port.cellsAt(p.reqs, at + 2)) < 0) {
                k += 1;
            }
            at += emon.Port.cellsAt(p.reqs, at);
        }
        return k;
    }
    public static int plCommit(emon.Planctx.Plan p) {
        // Every request of the round is answered. A `bytes` round: each answer must say ok (`fulfil-failed` otherwise), nothing is kept. A round of
        // requests: the answers join `ans` IN ID ORDER and the transcript's entries `[round request answer]` are written to `tx` in the same order.
        if (plOwed(p) != 0) {
            p.err = peBadRecord();
            emon.Port.textAscii(p.msg, "the round is not fully answered");
            return actError();
        }
        int n = emon.Port.cellsLen(p.reqs);
        int at = 0;
        while (at < n) {
            int rl = emon.Port.cellsAt(p.reqs, at);
            int id = emon.Port.cellsAt(p.reqs, at + 2);
            int ga = Plan.recFind(p.got, id);
            int al = emon.Port.cellsAt(p.got, ga);
            if (p.outk == 1) {
                if (emon.Port.cellsAt(p.got, ga + 3) != Plan.psOk()) {
                    p.err = peFulfilFailed();
                    p.errActual = emon.Port.cellsAt(p.got, ga + 3);
                    emon.Port.textAscii(p.msg, "fetching bytes: status ");
                    emon.Port.textI32(p.msg, emon.Port.cellsAt(p.got, ga + 3));
                    return actError();
                }
            } else {
                plCopy(p.ans, p.got, ga, al);
                emon.Port.cellsPush(p.tx, p.round);
                plCopy(p.tx, p.reqs, at, rl);
                plCopy(p.tx, p.got, ga, al);
            }
            at += rl;
        }
        emon.Port.cellsDrop(p.reqs, 0);
        emon.Port.cellsDrop(p.got, 0);
        p.outk = 0;
        return 0;
    }
